@push('scripts')<script>
(()=>{const list=document.getElementById('home-order-list'),input=document.getElementById('home-section-order');const sync=()=>input.value=[...list.querySelectorAll('[data-section]')].map(item=>item.dataset.section).join(',');list?.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;const item=button.closest('[data-section]');if(button.matches('[data-order-up]')&&item.previousElementSibling)list.insertBefore(item,item.previousElementSibling);if(button.matches('[data-order-down]')&&item.nextElementSibling)list.insertBefore(item.nextElementSibling,item);sync()});const frame=document.getElementById('storefront-preview');document.querySelectorAll('[data-preview-width]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-preview-width]').forEach(item=>item.classList.toggle('is-active',item===button));frame.style.width=button.dataset.previewWidth}));document.querySelector('[data-preview-reload]')?.addEventListener('click',()=>frame.contentWindow.location.reload())})();
</script>@endpush
@endsection
